use vstd::prelude::*;

verus! {
    fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
        requires
            x.len() > 0, // The input array must be non-empty
        ensures
            result.len() == x.len(), // The output array must have the same length as the input
            forall(|i: nat| 0 <= i < x.len() as nat ==> 
                (i == 0 || i == (x.len() as nat - 1)) ==> result[i] == 0.5 // Weights at endpoints
                && (i != 0 && i != (x.len() as nat - 1)) ==> result[i] == 1.0 // Weights in between
            ),
    {
        let n = x.len() as nat; // Get the length of the input array
        let mut result: Vec<f32> = vec![0.0; n as usize]; // Initialize the result array

        // Fill the result array with weights
        if n > 0 {
            result[0] = 0.5; // Set weight at the first index
            result[(n - 1) as usize] = 0.5; // Set weight at the last index
        }

        // Fill in the weights for the indices in between
        for i in 1..(n - 1) {
            result[i as usize] = 1.0; // Set weight for all other indices
        }

        result // Return the result array
    }
}
